import * as core from '@actions/core';
import { getPullRequestFirstCommit } from '../queries/getPullRequest.js';
import { computePullRequestClosedMetrics, computePullRequestDequeuedMetrics, computePullRequestOpenedMetrics, computePullRequestReadyForReviewMetrics, computePullRequestReviewRequestedMetrics, } from './metrics.js';
export const handlePullRequest = async (metricsClient, octokit, e, context, inputs) => {
    core.info(`Got pull request ${e.action} event: ${e.pull_request.html_url}`);
    if (e.action === 'opened') {
        return await metricsClient.submitMetrics(computePullRequestOpenedMetrics(e), 'pull request');
    }
    if (e.action === 'closed') {
        core.info(`Finding the first commit of the pull request #${e.pull_request.number}`);
        let pullRequestFirstCommit;
        try {
            pullRequestFirstCommit = await getPullRequestFirstCommit(octokit, {
                owner: context.repo.owner,
                name: context.repo.repo,
                number: e.pull_request.number,
            });
        }
        catch (error) {
            core.warning(`Could not get the pull request: ${String(error)}`);
        }
        return await metricsClient.submitMetrics(computePullRequestClosedMetrics(e, pullRequestFirstCommit, inputs), 'pull request');
    }
    if (e.action === 'ready_for_review') {
        return await metricsClient.submitMetrics(computePullRequestReadyForReviewMetrics(e), 'pull request');
    }
    if (e.action === 'review_requested') {
        return await metricsClient.submitMetrics(computePullRequestReviewRequestedMetrics(e), 'pull request');
    }
    if (e.action === 'dequeued') {
        return await metricsClient.submitMetrics(computePullRequestDequeuedMetrics(e), 'pull request');
    }
    core.warning(`Not supported action ${e.action}`);
};
