import assert from 'node:assert';
const query = /* GraphQL */ `
  query getCheckSuite($node_id: ID!) {
    node(id: $node_id) {
      __typename
      ... on CheckSuite {
        checkRuns(first: 100, filterBy: { checkType: LATEST }) {
          nodes {
            databaseId
            annotations(first: 10) {
              nodes {
                message
              }
            }
          }
        }
      }
    }
  }
`;
export const getCompletedCheckSuite = async (o, v) => {
    const r = await o.graphql(query, v);
    return {
        node: {
            __typename: 'CheckSuite',
            checkRuns: extractCheckRuns(r),
        },
    };
};
export const extractCheckRuns = (r) => {
    assert(r.node != null);
    assert.strictEqual(r.node.__typename, 'CheckSuite');
    const checkRuns = [];
    for (const checkRun of r.node.checkRuns?.nodes ?? []) {
        if (checkRun == null) {
            continue;
        }
        const annotations = [];
        for (const annotation of checkRun.annotations?.nodes ?? []) {
            if (annotation == null) {
                continue;
            }
            annotations.push(annotation);
        }
        checkRuns.push({
            ...checkRun,
            annotations: {
                nodes: annotations,
            },
        });
    }
    return { nodes: checkRuns };
};
